{"file_path": "C:\Users\UserX\.zcode\workspace\default\parse-log.js", "content": "const fs = require('fs');
const path = require('path');

const dir = 'C:/Users/UserX/.zcode/cli/log';
const files = process.argv.slice(2).length ? process.argv.slice(2) : ['zcode-2026-10-08.jsonl'];

const seen = new Map();

for (const f of files) {
  const full = path.join(dir, f);
  if (!fs.existsSync(full)) continue;
  const lines = fs.readFileSync(full, 'utf8').split('\n');
  for (const line of lines) {
    if (!line.trim()) continue;
    let obj;
    try { obj = JSON.parse(line); } catch { continue; }
    const ev = obj.event || '';
    if (!/failed|error/i.test(ev)) continue;
    const ctx = obj.context || {};
    const prov = ctx.providerId || ctx.model || '';
    if (!String(prov).includes('new-provider') && !String(ctx.baseURL || '').includes('xiaoshengapi')) continue;

    // Collect error-ish fields anywhere in the object
    const errs = [];
    const walk = (o, p) => {
      if (o == null) return;
      if (typeof o === 'string') return;
      if (Array.isArray(o)) { o.forEach((v, i) => walk(v, p + '[' + i + ']')); return; }
      if (typeof o === 'object') {
        for (const [k, v] of Object.entries(o)) {
          if (/error|message|status|code|body|response|detail|reason|limit|token|fail/i.test(k)) {
            if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') {
              errs.push(p + '.' + k + ' = ' + String(v).slice(0, 1200));
            }
          }
          walk(v, p + '.' + k);
        }
      }
    };
    walk(obj, '');
    const key = ev + '|' + errs.join('|');
    if (!seen.has(key)) {
      seen.set(key, { count: 0, ts: obj.timestamp, ev, model: ctx.modelId, sample: errs });
    }
    seen.get(key).count++;
  }
}

const out = [...seen.values()].sort((a, b) => b.count - a.count);
for (const r of out) {
  console.log('='.repeat(90));
  console.log(`EVENT: ${r.ev}  x${r.count}  model=${r.model}  ts=${r.ts}`);
  for (const e of r.sample) console.log('   ' + e);
}
console.log('\nTotal distinct error signatures: ' + out.length);
"}

{"content": "const fs = require('fs');
const path = require('path');
const dir = 'C:/Users/UserX/.zcode/cli/log';
const files = fs.readdirSync(dir).filter(f => f.endsWith('.jsonl'));

const needles = /(context|token|window|413|prompt_tokens|max_tokens|too (long|large)|length)/i;
const hits = [];

for (const f of files) {
  const lines = fs.readFileSync(path.join(dir, f), 'utf8').split('\n');
  for (const line of lines) {
    if (!line.trim() || !needles.test(line)) continue;
    let o; try { o = JSON.parse(line); } catch { continue; }
    const ctx = o.context || {};
    const bx = ctx.baseURL || '';
    const pid = ctx.providerId || '';
    if (!String(pid).includes('new-provider') && !String(bx).includes('xiaoshengapi')) continue;
    hits.push({ f, ts: o.timestamp, ev: o.event, model: ctx.modelId, o });
  }
}
console.log('matching events: ' + hits.length + '\n');
const shown = new Set();
for (const h of hits) {
  const sig = h.ev + '|' + Object.keys(h.o.context || {}).sort().join(',');
  if (shown.has(sig)) continue;
  shown.add(sig);
  console.log('#'.repeat(90));
  console.log(h.f, h.ts, h.ev, h.model);
  console.log(JSON.stringify(h.o, null, 2).slice(0, 6000));
  console.log();
}
