async function probe(model, chars, label) {
  const filler = 'word '.repeat(Math.ceil(chars / 5)).slice(0, chars);
  const body = JSON.stringify({
    model,
    messages: [{ role: 'user', content: filler + '\nReply with the single word OK.' }],
    max_tokens: 4,
    stream: false,
  });
  const t0 = Date.now();
  try {
    const res = await fetch(BASE, {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' },
      body,
      signal: AbortSignal.timeout(120000),
    });
    const text = await res.text();
    return { label, model, chars, bytes: body.length, status: res.status, ms: Date.now() - t0, body: text.slice(0, 500) };
  } catch (e) {
    return { label, model, chars, bytes: body.length, status: 'ERR', ms: Date.now() - t0, body: String(e.message || e).slice(0, 300) };
  }
}

(async () => {
  const model = process.argv[2] || 'deepseek-v4.1-flash';
  const sizes = process.argv.slice(3).map(Number);
  const results = [];
  for (const s of sizes) {
    const r = await probe(model, s, `chars=${s}`);
    results.push(r);
    console.log(`[${r.status}] ${model} chars=${s} bodyBytes=${r.bytes} ${r.ms}ms :: ${r.body.replace(/\s+/g, ' ').slice(0, 300)}`);
