{"content": "const KEY = 'sk-<已脱敏>';
const BASE = 'https://xiaoshengapi.top/v1/chat/completions';

// Ask the model to report a canary placed at the START and at the END of the input.
// If the head canary is still visible but a middle/end marker is not, the input was truncated from the tail.
function build(chars, canary) {
  const filler = 'word '.repeat(Math.ceil(chars / 5)).slice(0, chars);
  return `CANARY=${canary}_HEAD\n${filler}\nCANARY=${canary}_TAIL\nIgnore the filler. Reply with exactly the two CANARY lines you can see.`;
}

async function probe(model, chars, maxTokens = 200) {
  const canary = 'zqx' + Math.random().toString(36).slice(2, 8);
  const content = build(chars, canary);
  const body = JSON.stringify({ model, messages: [{ role: 'user', content }], max_tokens: maxTokens, stream: false });
  const t0 = Date.now();
  try {
    const res = await fetch(BASE, {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' },
      body,
      signal: AbortSignal.timeout(180000),
    });
    const txt = await res.text();
    let j = null; try { j = JSON.parse(txt); } catch {}
    const u = j?.usage || {};
    const msg = j?.choices?.[0]?.message || {};
    const all = (msg.content || '') + '|' + (msg.reasoning_content || '');
    return {
      status: res.status, chars, bodyBytes: body.length, ms: Date.now() - t0,
      prompt_tokens: u.prompt_tokens, completion_tokens: u.completion_tokens, total: u.total_tokens,
      seesHEAD: all.includes(canary + '_HEAD'), seesTAIL: all.includes(canary + '_TAIL'),
      finish: j?.choices?.[0]?.finish_reason,
      err: res.status !== 200 ? txt.slice(0, 400) : undefined,
      reply: res.status === 200 ? all.replace(/\s+/g, ' ').slice(0, 200) : undefined,
    };
  } catch (e) {
    return { status: 'ERR', chars, bodyBytes: body.length, ms: Date.now() - t0, err: String(e.message || e).slice(0, 300) };
  }
}

(async () => {
  const model = process.argv[2] || 'deepseek-v4.1-flash';
  const sizes = process.argv.slice(3).map(Number);
  const out = [];
  for (const s of sizes) {
    const r = await probe(model, s);
    out.push(r);
    console.log(JSON.stringify(r));
    await new Promise((x) => setTimeout(x, 1000));
  }
  require('fs').appendFileSync('sweep2.jsonl', out.map((r) => JSON.stringify(r)).join('\n') + '\n');
})();
", "file_path": "C:\Users\UserX\.zcode\workspace\default\probe2.js"}

