{"content": "const fs = require('fs');
const dir = 'C:/Users/UserX/.zcode/cli/log/';
const files = ['zcode-2026-10-08.jsonl', 'zcode-2026-10-07.jsonl'];
const SESS = 'sess_400ed897-2a06-46a5-968e-5fb988c17205';

for (const f of files) {
  const lines = fs.readFileSync(dir + f, 'utf8').split('\n');
  const rows = [];
  const keyCount = new Map();
  for (const line of lines) {
    if (!line.includes(SESS)) continue;
    let o; try { o = JSON.parse(line); } catch { continue; }
    rows.push(o);
    for (const k of Object.keys(o.context || {})) keyCount.set(k, (keyCount.get(k) || 0) + 1);
  }
  console.log('='.repeat(100));
  console.log(f + '  events for ' + SESS + ' = ' + rows.length);
  console.log('context keys seen: ' + JSON.stringify([...keyCount.entries()].sort((a,b)=>b[1]-a[1])));
  // distinct event names
  const evs = new Map();
  for (const r of rows) evs.set(r.event, (evs.get(r.event) || 0) + 1);
  console.log('event names: ' + JSON.stringify([...evs.entries()].sort((a,b)=>b[1]-a[1]), null, 0));
  // print any event whose context has numeric size-ish fields
  const interesting = rows.filter(r => {
    const s = JSON.stringify(r.context || {});
    return /(sizeBytes|requestBytes|estimated|Tokens|chars|length|count"|compact)/i.test(s);
  });
  console.log('events with size-ish fields: ' + interesting.length);
  const seen = new Set();
  for (const r of interesting.slice(0, 40)) {
    const k = r.event + '|' + Object.keys(r.context || {}).join(',');
    if (seen.has(k)) continue; seen.add(k);
    console.log('--- ' + r.timestamp + ' ' + r.event + ' ' + (r.context?.modelId || ''));
    console.log('    ' + JSON.stringify(r.context).slice(0, 1500));
  }
}
