{"content": "const KEY = 'sk-<已脱敏>';
const BASE = 'https://xiaoshengapi.top/v1/chat/completions';

async function probeStream(model, chars, maxTokens) {
  const filler = 'word '.repeat(Math.ceil(chars / 5)).slice(0, chars);
  const body = JSON.stringify({
    model,
    messages: [{ role: 'user', content: filler + '\nSay OK.' }],
    max_tokens: maxTokens,
    stream: true,
    stream_options: { include_usage: true },
  });
  const t0 = Date.now();
  try {
    const res = await fetch(BASE, {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json', Accept: 'text/event-stream' },
      body,
      signal: AbortSignal.timeout(240000),
    });
    const txt = await res.text();
    const usage = txt.match(/"usage":\{[^}]*\}/g);
    return {
      model, chars, max_tokens: maxTokens, stream: true, status: res.status, ms: Date.now() - t0,
      sseLen: txt.length, usage: usage ? usage[usage.length - 1] : null,
      head: txt.slice(0, 300).replace(/\s+/g, ' '),
      err: res.status !== 200 ? txt.replace(/\s+/g, ' ').slice(0, 500) : undefined,
    };
  } catch (e) {
    return { model, chars, max_tokens: maxTokens, stream: true, status: 'ERR', ms: Date.now() - t0, err: String(e.message || e).slice(0, 300) };
  }
}

(async () => {
  const model = process.argv[2];
  const sizes = process.argv.slice(3).map(Number);
  for (const s of sizes) {
    const r = await probeStream(model, s, 64);
    console.log(JSON.stringify(r));
    await new Promise((x) => setTimeout(x, 1000));
  }
})();
