async function run(label, mutate) {
  const body = JSON.parse(JSON.stringify(base));
  mutate(body);
  const t0 = Date.now();
  let status, txt;
  try {
    const res = await fetch(URL, {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(300000),
    });
    status = res.status; txt = await res.text();
  } catch (e) { status = 'ERR'; txt = String(e.message || e); }
  const m = txt.match(/"message":"([^"]{0,300})"/);
  console.log(`${label.padEnd(52)} HTTP=${String(status).padEnd(5)} ${Date.now() - t0}ms :: ${m ? m[1] : txt.replace(/\s+/g, ' ').slice(0, 200)}`);
  await new Promise((r) => setTimeout(r, 700));
}

