// size in MEGAbytes of raw base64 image payload -> body
async function probe(mb) {
  const chars = Math.round(mb * 1048576);
  // plausible base64-ish filler unique enough not to be compressed away
  const b64 = Buffer.alloc(chars).map((_, i) => (i * 7919) % 256).toString('base64').slice(0, chars);
  const body = JSON.stringify({
    model: 'deepseek-v4.1-flash',
    messages: [{
      role: 'user',
      content: [
        { type: 'text', text: 'Reply with OK.' },
        { type: 'image_url', image_url: { url: 'data:image/png;base64,' + b64 } },
      ],
    }],
    max_tokens: 4,
    stream: false,
  });
  const t0 = Date.now();
  let status, txt;
  try {
    const res = await fetch(URL, {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' },
      body,
      signal: AbortSignal.timeout(300000),
    });
    status = res.status; txt = await res.text();
  } catch (e) { status = 'ERR'; txt = String(e.message || e); }
  const m = txt.match(/"message":"([^"]{0,200})"/);
  console.log(`reqBodyMB=${(body.length / 1048576).toFixed(2).padEnd(7)} HTTP=${String(status).padEnd(5)} ${String(Date.now() - t0).padEnd(7)}ms :: ${m ? m[1] : txt.replace(/\s+/g, ' ').slice(0, 160)}`);
  await new Promise((r) => setTimeout(r, 500));
  return { mb, status, bodyLen: body.length };
}

(async () => {
  const sizes = process.argv.slice(2).map(Number);
  const out = [];
  for (const s of sizes) out.push(await probe(s));
