{"content": "const fs = require('fs');
const KEY = 'sk-<已脱敏>';
const URL = 'https://xiaoshengapi.top/v1/chat/completions';

function buildBody(targetBytes) {
  // header part with a tiny valid-ish image slot; we then pad the text to hit targetBytes exactly
  const head = { model: 'deepseek-v4.1-flash', messages: [{ role: 'user', content: [{ type: 'text', text: '' }] }], max_tokens: 4, stream: false };
  const template = JSON.stringify(head);
  const overhead = Buffer.byteLength(template, 'utf8');
  const pad = targetBytes - overhead;
  if (pad < 0) throw new Error('target too small');
  head.messages[0].content[0].text = 'x'.repeat(pad);
  const body = JSON.stringify(head);
  return { body, len: Buffer.byteLength(body, 'utf8') };
}

async function probe(targetBytes) {
  const { body, len } = buildBody(targetBytes);
