{"content": "#!/usr/bin/env node
/**
 * ZCode 媒体预算补丁 (40 MiB -> 6 MiB)
 * 用法:
 *   node patch-zcode-media.js apply     # 应用补丁
 *   node patch-zcode-media.js revert    # 回滚到最近备份
 *   node patch-zcode-media.js status    # 查看当前状态
 */
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const BUNDLE = 'C:\\Users\\UserX\\AppData\\Local\\Programs\\ZCode\\resources\\glm\\zcode.cjs';
const BACKUP_DIR = 'C:\\Users\\UserX\\.zcode\\backup\\zcode-cjs';
const FROM = 'dwa=40*1024*1024';
const TO = 'dwa=6*1024*1024';

function status() {
  const src = fs.readFileSync(BUNDLE, 'utf8');
  const fromN = src.split(FROM).length - 1;
  const toN = src.split(TO).length - 1;
  console.log(`bundle: ${BUNDLE}`);
  console.log(`  size       : ${fs.statSync(BUNDLE).size}`);
  console.log(`  mtime      : ${fs.statSync(BUNDLE).mtime.toISOString()}`);
  console.log(`  unpatched  ("${FROM}") : ${fromN}`);
  console.log(`  patched    ("${TO}") : ${toN}`);
  if (fromN === 1 && toN === 0) console.log('  => 状态: 原始未打补丁');
  else if (fromN === 0 && toN === 1) console.log('  => 状态: 已打补丁 (6 MiB)');
  else console.log('  => 状态: 异常(标记数不为 1)，请勿继续操作');
  const snaps = fs.existsSync(BACKUP_DIR) ? fs.readdirSync(BACKUP_DIR).filter((f) => f.endsWith('.cjs')).sort() : [];
  console.log(`  backups    : ${snaps.length ? snaps.join(', ') : '(无)'}`);
}

function checkSyntax(file) {
  try {
    execFileSync(process.execPath, ['--check', file], { stdio: 'pipe' });
    return null;
  } catch (e) {
    return (e.stderr || e.stdout || Buffer.from('')).toString().slice(0, 800);
  }
}

function apply() {
  const src = fs.readFileSync(BUNDLE, 'utf8');
  const fromN = src.split(FROM).length - 1;
  const toN = src.split(TO).length - 1;
  if (fromN === 0 && toN === 1) { console.log('已打过补丁，无需重复操作。'); return; }
  if (fromN !== 1) throw new Error(`补丁标记唯一性校验失败: "${FROM}" 出现 ${fromN} 次，为安全起见终止。`);

  // 1. 备份
  fs.mkdirSync(BACKUP_DIR, { recursive: true });
  const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
  const backup = path.join(BACKUP_DIR, `zcode.cjs.orig-${stamp}`);
  fs.copyFileSync(BUNDLE, backup);
  console.log(`已备份 -> ${backup}`);

  // 2. 写入临时文件并校验语法
  const patched = src.replace(FROM, TO);
  const tmp = BUNDLE + '.patched.tmp';
  fs.writeFileSync(tmp, patched, 'utf8');
  const err = checkSyntax(tmp);
  if (err) { fs.unlinkSync(tmp); throw new Error('补丁后语法校验失败，已放弃写入:\n' + err); }
  console.log('语法校验通过 (node --check)');

  // 3. 原子替换
  fs.copyFileSync(tmp, BUNDLE);
  fs.unlinkSync(tmp);
  fs.writeFileSync(path.join(BACKUP_DIR, 'LAST_PATCH.txt'),
    `patched_at=${new Date().toISOString()}\nfrom=${FROM}\nto=${TO}\nbundle=${BUNDLE}\nbackup=${backup}\n`);
  console.log('补丁已应用。请完全退出并重启 ZCode 生效。');
}

function revert() {
  if (!fs.existsSync(BACKUP_DIR)) throw new Error('备份目录不存在，无法回滚。');
  const snaps = fs.readdirSync(BACKUP_DIR).filter((f) => f.startsWith('zcode.cjs.orig-')).sort();
  if (!snaps.length) throw new Error('未找到备份文件。');
  const newest = path.join(BACKUP_DIR, snaps[snaps.length - 1]);
  const err = checkSyntax(newest);
  if (err) throw new Error('备份文件语法校验失败，拒绝回滚:\n' + err);
  fs.copyFileSync(newest, BUNDLE);
  console.log(`已回滚 -> 使用备份 ${newest}`);
  console.log('请完全退出并重启 ZCode 生效。');
}

const cmd = (process.argv[2] || 'status').toLowerCase();
try {
  if (cmd === 'apply') apply();
  else if (cmd === 'revert' || cmd === 'rollback') revert();
  else status();
} catch (e) {
  console.error('ERROR: ' + e.message);
  process.exit(1);
}
